function y = fcn(u)
%Function description:
%  Control the range of the remote control input from RCMin to RCMax, and set
%  a dead zone with a dead zone size of ±deadZone,the output y is
%  normalized to 0~1.You can get the RC calibration parameters in QGC.
RCMin = 1100;
RCMax = 1900;
RCMid = (RCMin + RCMax)/2;
deadZoneRate = 0.05;
deadZone = deadZoneRate*(RCMax - RCMin);
k = 1/(RCMax - RCMid - deadZone);
%Limiting
if(u < RCMin)
    u = RCMin;
elseif(u > RCMax)
    u = RCMax;
end
%dead zone and normalize
 if(u > RCMid + deadZone)
    y = (u-RCMid - deadZone)*k;
 elseif(u < RCMid - deadZone)
     y = (u - RCMid + deadZone)*k;
 else
     y = 0;
 end

 end

