function Reb = fcn(q)
%Function description;
%  The rotation matrix of the Aircraft-Body Coordinate Frame (ABCF) to the
%  Earth-Fixed Coordinate Frame (EFCF) is obtained from the quaternions
Reb = [q(1)*q(1) + q(2)*q(2) - q(3)*q(3) - q(4)*q(4), 2*(q(2)*q(3) - q(1)*q(4)), 2*(q(2)*q(4) + q(1)*q(3))
           2*(q(2)*q(3) + q(1)*q(4)), q(1)*q(1) - q(2)*q(2) + q(3)*q(3) - q(4)*q(4), 2*(q(3)*q(4) - q(1)*q(2))
           2*(q(2)*q(4) - q(1)*q(3)), 2*(q(3)*q(4) + q(1)*q(2)), q(1)*q(1) - q(2)*q(2) - q(3)*q(3) + q(4)*q(4)];

function y = fcn(q)
 %Function description:
%  Quaternions to Euler
phi = atan2(2*(q(1)*q(2) + q(3)*q(4)), (1 - 2*(q(2)*q(2) + q(3)*q(3))));
theta = asin(2*(q(1)*q(3) - q(2)*q(4)));
psi = atan2(2*(q(1)*q(4) + q(2)*q(3)), (1 - 2*(q(3)*q(3) + q(4)*q(4))));
y = [phi theta psi];

function qdot = fcn(pqr, q)
%Function description:
%  Quaternions model
qdot = 0.5*[0, -pqr(1), -pqr(2), -pqr(3); pqr(1), 0, pqr(3), -pqr(2); pqr(2), -pqr(3), 0, pqr(1); pqr(3), pqr(2), -pqr(1), 0]*q;

function q = fcn(EulerAngle)
%Function description:
%  Get quaternions from Euler angle
q0 =  cos(EulerAngle(1)/2)*cos(EulerAngle(2)/2)*cos(EulerAngle(3)/2) + sin(EulerAngle(1)/2)*sin((EulerAngle(2)/2))*sin((EulerAngle(3)/2));
q1 = sin(EulerAngle(1)/2)*cos(EulerAngle(2)/2)*cos(EulerAngle(3)/2) - cos(EulerAngle(1)/2)*sin((EulerAngle(2)/2))*sin((EulerAngle(3)/2));
q2 = cos(EulerAngle(1)/2)*sin(EulerAngle(2)/2)*cos(EulerAngle(3)/2) + sin(EulerAngle(1)/2)*cos((EulerAngle(2)/2))*sin((EulerAngle(3)/2));
q3 = cos(EulerAngle(1)/2)*cos(EulerAngle(2)/2)*sin(EulerAngle(3)/2) - sin(EulerAngle(1)/2)*sin((EulerAngle(2)/2))*cos((EulerAngle(3)/2));
q = [q0 q1 q2 q3]';

function [M1, M2, M3, M4] = motor_mixer(Roll, Pitch, Yaw, Thrust)
%Function description:
%  Control allocation. The quadrotor type is X-configuration,
%  and the airframe is as follows:
%3↓   1↑
 %  \ /
 %  / \
 %2↑   4↓
%Input：
%  Roll, Pitch, Yaw: attitude controller output.
%  Thrust

idle_PWM = 1000;
scale = 1000;

M1 = (Thrust - Roll + Pitch + Yaw) * scale + idle_PWM;
M2 = (Thrust + Roll - Pitch + Yaw) * scale + idle_PWM;
M3 = (Thrust + Roll + Pitch - Yaw) * scale + idle_PWM;
M4 = (Thrust - Roll - Pitch - Yaw) * scale + idle_PWM;
